body:
{
  "id": "hdf5",
  "version": "schemaxis.hdf5/1",
  "adaptor": "schemaxis.adaptors.hdf5.adaptor",
  "declarations": "schemaxis.adaptors.hdf5.adaptor:DECLARATIONS",
  "runtimeFamily": "3.16",
  "execution": "HDF5 scientific data files through h5py 3.16.0 (bundled HDF5 2.0.0) in an isolated process: create typed hierarchical files (groups, numeric/complex/string/enum/compound/vlen/reference/opaque datasets and attributes, chunking, gzip/lzf/szip/shuffle/fletcher32/scale-offset filters, fill values, resizable datasets, dimension scales, units, soft/hard/external links, committed datatypes, virtual datasets and external raw storage, file drivers and format bounds), inspect and audit existing files against typed expectations, extract hyperslab/point/field selections to CSV/NPY/JSON, edit captured copies (create, delete, move, copy, attributes, selection writes, resize, append, scales, relayout, repack), write XDMF mesh/field time series, append SWMR series observed by concurrent readers and compare files with tolerances; every publication is checked against host-computed expectations by a fresh h5py readback and the independent HDF Group h5dump 2.2.0 XML reading",
  "executables": [
    "python3"
  ],
  "keywords": [
    "HDF5",
    "h5py",
    "hierarchical data format",
    "HDF5 file"
  ],
  "display": {
    "name": "HDF5",
    "mark": "H5",
    "colour": "#1f5f8b"
  },
  "capabilities": "schemaxis.adaptors.hdf5.capabilities:catalogue",
  "executionCapabilities": {
    "modes": [
      "process"
    ],
    "mpi": false
  },
  "consoleTemplate": {
    "version": "schemaxis.hdf5/1",
    "operation": "createFile",
    "file": {
      "name": "measurements.h5"
    },
    "objects": [
      {
        "path": "/run/time",
        "type": {
          "class": "float",
          "bits": 64
        },
        "shape": [
          5
        ],
        "data": {
          "source": "linspace",
          "start": 0,
          "stop": 2
        },
        "units": "s",
        "scale": "time"
      },
      {
        "path": "/run/pressure",
        "type": {
          "class": "float",
          "bits": 32
        },
        "shape": [
          5
        ],
        "data": {
          "source": "values",
          "values": [
            101.3,
            101.1,
            100.8,
            100.9,
            101.2
          ]
        },
        "units": "kPa",
        "dimensions": [
          {
            "axis": 0,
            "label": "time",
            "scales": [
              "/run/time"
            ]
          }
        ]
      }
    ]
  },
  "routes": {
    "schemaxis.hdf5/1": {
      "module": "schemaxis.adaptors.hdf5.adaptor",
      "schema": "schemaxis.adaptors.hdf5.adaptor:schema",
      "graphEditing": false,
      "workflow": true,
      "compose": true,
      "timeBatches": false,
      "schemaName": "hdf5",
      "acceptedArtifacts": [
        "file",
        "table"
      ],
      "scheduled": true,
      "hooks": {
        "query": "schemaxis.adaptors.hdf5.adaptor:query",
        "reusableInputs": "schemaxis.adaptors.hdf5.adaptor:reusableInputs",
        "resources": "schemaxis.adaptors.hdf5.adaptor:resources"
      },
      "runOptions": {
        "h5dump": "hdf5H5dump",
        "mpiPython": "hdf5Mpi",
        "mpiexec": "hdf5Mpiexec"
      }
    }
  },
  "consoleCapabilities": {
    "authoredSessions": true,
    "multipleDocuments": true,
    "liveGeometry": false,
    "nativeEditReverseSync": false
  },
  "cliOptions": [
    {
      "flag": "--hdf5",
      "dest": "hdf5",
      "help": "Absolute isolated Python interpreter containing exactly h5py 3.16.0 (bundled HDF5 2.0.0) and NumPy 2.5.4"
    },
    {
      "flag": "--hdf5-h5dump",
      "dest": "hdf5H5dump",
      "help": "Absolute HDF Group h5dump 2.2.0 executable used as the independent consumer for verification"
    },
    {
      "flag": "--hdf5-mpi",
      "dest": "hdf5Mpi",
      "help": "Absolute Python with h5py 3.16.0 built against parallel HDF5 2.0.0 and mpi4py, for parallelWrite"
    },
    {
      "flag": "--hdf5-mpiexec",
      "dest": "hdf5Mpiexec",
      "help": "Absolute Open MPI 4.1 mpiexec matching the parallel h5py build, for parallelWrite"
    }
  ]
}
